"use client";

import { useMemo, useState } from "react";
import feed from "../../../services/newsroom/feeds/japan-earthquake.json";

// Generated by the Python newsroom (services/newsroom). Regenerate with:
//   cd services/newsroom && python3 -m worldwire ../../contracts/fixtures/japan-earthquake.json > feeds/japan-earthquake.json
// The feed holds one story per event in the fixture timeline. The panel shows a
// story only once the simulation stream has applied its event, so seeking or
// replaying (a new snapshot) hides stories from the future again.
type NewsItem = (typeof feed)[number];

export function focusNewsItem(item: NewsItem) {
  window.dispatchEvent(new CustomEvent("worldsim:focus", { detail: item.focus }));
}

export function visibleNews(items: readonly NewsItem[], appliedEventIds: readonly string[]) {
  const applied = new Set(appliedEventIds);
  return items.filter((item) => applied.has(item.event_id));
}

export function WorldWire({ appliedEventIds }: { appliedEventIds: readonly string[] }) {
  const [activeId, setActiveId] = useState<string | null>(null);
  const items = useMemo(() => visibleNews(feed, appliedEventIds), [appliedEventIds]);

  return (
    <section className="world-wire" aria-labelledby="world-wire-title" aria-live="polite">
      <div className="world-wire-heading">
        <h3 id="world-wire-title" className="section-label">WORLD//WIRE</h3>
        <span className="world-wire-note">Fictional news</span>
      </div>
      {items.length === 0 ? (
        <p className="world-wire-empty">No reports yet. Play the simulation to receive its first applied event.</p>
      ) : (
        <ul className="world-wire-list">
          {items.map((item) => (
            <li key={item.id}>
              <button
                type="button"
                className="wire-card"
                aria-pressed={activeId === item.id}
                onClick={() => {
                  setActiveId(item.id);
                  focusNewsItem(item);
                }}>
                <span className="wire-meta">
                  <span className="wire-label">{item.label}</span>
                  <span>{item.sim_time_label} SIM TIME</span>
                </span>
                <span className="wire-headline">{item.headline}</span>
                <span className="wire-dek">{item.dek}</span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
